const inCBLinkerClass = String.raw`\u094D\u09CD\u0ACD\u0B4D\u0C4D\u0D4D\u1039\u17D2\u1A60\u1B44\u1BAB\uA9C0\uAAF6\u{10A3F}\u{11133}\u{113D0}\u{1193E}\u{11A47}\u{11A99}\u{11F42}`
// Composed from shared class strings so each Unicode table ships in the
// bundle once; `endingConjunctLinker` reuses all three.
const reInCBConsonant = new RegExp(`^[${inCBConsonantClass}]$`, 'u')
const reInCBExtend = new RegExp(`^[${inCBExtendClass}]$`, 'u')
const reInCBLinker = new RegExp(`^[${inCBLinkerClass}]$`, 'u')

const getCodepointType = (char: string, code: number): CodepointType => {
  let type = CodepointType.Any
  if (char.search(reExtend) !== -1) {
    type |= CodepointType.Extend
  }
  if (code === 0x200d) {
    type |= CodepointType.ZWJ
  }
  if (code >= 0x1f1e6 && code <= 0x1f1ff) {
    type |= CodepointType.RI
  }
  if (char.search(rePrepend) !== -1) {
    type |= CodepointType.Prepend
  }
  if (char.search(reSpacingMark) !== -1) {
    type |= CodepointType.SpacingMark
  }
  if (char.search(reL) !== -1) {
    type |= CodepointType.L
  }
  if (char.search(reV) !== -1) {
    type |= CodepointType.V
  }
  if (char.search(reT) !== -1) {
    type |= CodepointType.T
  }
  if (code >= hangulSyllableFirst && code <= hangulSyllableLast) {
    // Unicode composes each precomposed syllable as `0xAC00 + (L * 21 + V) * 28 + T`,
    // so the syllables with no trailing consonant (`T = 0`) are the LV ones.
    type |=
      (code - hangulSyllableFirst) % hangulTrailingConsonantCount === 0
        ? CodepointType.LV
        : CodepointType.LVT
  }
  if (char.search(reExtPict) !== -1) {
    type |= CodepointType.ExtPict
  }
  if (char.search(reInCBConsonant) !== -1) {
    type |= CodepointType.InCBConsonant
  }
  if (char.search(reInCBExtend) !== -1) {
    type |= CodepointType.InCBExtend
  }
  if (char.search(reInCBLinker) !== -1) {
    type |= CodepointType.InCBLinker
  }

  return type
}

const hangulSyllableFirst = 0xac00
const hangulSyllableLast = 0xd7a3
const hangulTrailingConsonantCount = 28

function intersects(x: CodepointType, y: CodepointType) {
  return (x & y) !== 0
}

const NonBoundaryPairs: [CodepointType, CodepointType][] = [
  // GB6
  [
    CodepointType.L,
    CodepointType.L | CodepointType.V | CodepointType.LV | CodepointType.LVT,
  ],
  // GB7
  [CodepointType.LV | CodepointType.V, CodepointType.V | CodepointType.T],
  // GB8
  [CodepointType.LVT | CodepointType.T, CodepointType.T],
  // GB9
  [CodepointType.Any, CodepointType.Extend | CodepointType.ZWJ],
  // GB9a
  [CodepointType.Any, CodepointType.SpacingMark],
  // GB9b
  [CodepointType.Prepend, CodepointType.Any],
  // GB9c
  [
    CodepointType.InCBLinker | CodepointType.InCBExtend,
    CodepointType.InCBConsonant,
  ],
  // GB11
  [CodepointType.ZWJ, CodepointType.ExtPict],
  // GB12 and GB13
  [CodepointType.RI, CodepointType.RI],
]

function isBoundaryPair(left: CodepointType, right: CodepointType) {
  return (
    NonBoundaryPairs.findIndex(
      (r) => intersects(left, r[0]) && intersects(right, r[1]),
    ) === -1
  )
}

const endingEmojiZWJ = /\p{ExtPict}[\p{Gr_Ext}\p{EMod}]*\u200D$/u
const endsWithEmojiZWJ = (str: string): boolean => {
  return str.search(endingEmojiZWJ) !== -1
}

// GB9c: Consonant [Extend Linker]* Linker [Extend Linker]* left context.
const endingConjunctLinker = new RegExp(
  `[${inCBConsonantClass}](?:[${inCBExtendClass}${inCBLinkerClass}])*[${inCBLinkerClass}](?:[${inCBExtendClass}${inCBLinkerClass}])*$`,
  'u',
)
const endsWithConjunctLinker = (str: string): boolean => {
  return str.search(endingConjunctLinker) !== -1
}

const endingRIs = /\p{RI}+$/gu
const endsWithOddNumberOfRIs = (str: string): boolean => {
  const match = str.match(endingRIs)
  if (match === null) {
    return false
  } else {
    // A RI is represented by a surrogate pair.
    const numRIs = match[0].length / 2
    return numRIs % 2 === 1
  }
}
