import {rem} from '@sanity/ui'
import {styled} from 'styled-components'
import {Text, Flex, Box, VStack} from 'ui5'
import {getDevicePixelRatio} from 'use-device-pixel-ratio'

import {LinearProgress} from '../../progress/LinearProgress'
import {Media} from '../_common/Media'
import {PREVIEW_SIZES} from '../constants'
import {renderPreviewNode} from '../helpers'
import {type PreviewMediaDimensions, type PreviewProps} from '../types'

const DEFAULT_MEDIA_DIMENSIONS: PreviewMediaDimensions = {
  ...PREVIEW_SIZES.block.media,
  aspect: 1,
  fit: 'crop',
  dpr: getDevicePixelRatio(),
}

const HeaderFlex = styled(Flex).attrs({alignItems: 'center'})`
  min-height: ${rem(PREVIEW_SIZES.block.media.height)};
`

/**
 * @hidden
 * @beta */
export function BlockPreview(props: Omit<PreviewProps<'block'>, 'renderDefault'>) {
  const {
    actions,
    title,
    subtitle,
    description,
    mediaDimensions = DEFAULT_MEDIA_DIMENSIONS,
    media,
    progress,
    status,
    children,
  } = props

  const isUploading = typeof progress === 'number' && progress > -1

  return (
    <VStack data-testid="block-preview" gap={1}>
      <HeaderFlex data-testid="block-preview__header">
        {media && <Media dimensions={mediaDimensions} layout="block" media={media as any} />}

        <Flex
          flexBasis="0%"
          flexGrow={1}
          paddingLeft={media ? 2 : 1}
          flexDirection="column"
          gap={3}
        >
          <Flex flexDirection="column" gap={2}>
            <Text
              size={1}
              truncate={1}
              weight="medium"
              as="div"
              trim={true}
              style={{color: 'var(--card-fg-color)'}}
            >
              {title ? renderPreviewNode(title, 'block') : 'Untitled'}
            </Text>

            {subtitle && (
              <Text
                muted
                size={1}
                truncate={1}
                as="div"
                trim={true}
                style={{color: 'var(--card-muted-fg-color)'}}
              >
                {renderPreviewNode(subtitle, 'block')}
              </Text>
            )}
          </Flex>

          {description && (
            <Text
              muted
              size={1}
              truncate={1}
              as="div"
              trim={true}
              style={{color: 'var(--card-muted-fg-color)'}}
            >
              {renderPreviewNode(description, 'block')}
            </Text>
          )}

          {isUploading && <LinearProgress value={progress} />}
        </Flex>

        <Flex gap={1} paddingLeft={1}>
          {status && (
            <Box paddingX={2} paddingY={3}>
              {renderPreviewNode(status, 'block')}
            </Box>
          )}

          {actions as any}
        </Flex>
      </HeaderFlex>

      {children && <div data-testid="block-preview__children">{children}</div>}
    </VStack>
  )
}
