import type {Schema} from '@portabletext/schema'
import {transformPoint} from '../point/transform-point'
import type {TextDirection} from '../types/types'
import type {EngineOperation} from './operation'
import type {Point} from './point'

/**
 * `PointRef` objects keep a specific point in a document synced over time as new
 * operations are applied to the editor. You can access their `current` property
 * at any time for the up-to-date point value.
 */

// oxlint-disable-next-line no-redeclare -- interface and its companion `PointRef` const live in separate TypeScript namespaces
export interface PointRef {
  current: Point | null
  affinity: TextDirection | null
  unref(): Point | null
}

interface PointRefInterface {
  transform: (
    context: {schema: Schema},
    ref: PointRef,
    op: EngineOperation,
  ) => void
}

// eslint-disable-next-line no-redeclare
export const PointRef: PointRefInterface = {
  transform(
    context: {schema: Schema},
    ref: PointRef,
    op: EngineOperation,
  ): void {
    const {current, affinity} = ref

    if (current == null) {
      return
    }

    const point = transformPoint(context, current, op, {affinity})
    ref.current = point

    if (point == null) {
      ref.unref()
    }
  },
}
