// Requests to the OAuth 2.1 endpoints of the Sanity API (`/v1/auth/oauth/*`).
//
// These use `fetch` rather than a Sanity client: the token and revocation endpoints are
// form-encoded, unversioned, and must never carry the credentials of the session they manage.

/** @internal */
export interface OAuthTokenResponse {
  access_token: string
  token_type: string
  expires_in: number
  refresh_token?: string
  /**
   * How many seconds the refresh token can go unused before it expires
   * (draft-ietf-oauth-refresh-token-expiration). Every renewal gives a new refresh token with the
   * full timeout.
   */
  refresh_token_timeout?: number
}

/**
 * An error response from an OAuth endpoint. `error` is the RFC 6749 error code when the server
 * sent one, e.g. `invalid_grant` for a refresh token that was already used, expired, or whose
 * session was revoked.
 *
 * @internal
 */
export class OAuthRequestError extends Error {
  readonly statusCode: number
  readonly error: string | undefined
  /** Whether the body had an `error` at all, whether or not it was a usable code. */
  readonly sentError: boolean

  constructor(statusCode: number, body: unknown) {
    const parsed =
      typeof body === 'object' && body !== null ? (body as Record<string, unknown>) : {}
    const rawError = typeof parsed.error === 'string' ? parsed.error : undefined
    const description =
      typeof parsed.error_description === 'string'
        ? parsed.error_description
        : typeof parsed.message === 'string'
          ? parsed.message
          : undefined
    super(
      `OAuth request failed (${statusCode})${rawError ? `: ${rawError}` : ''}${description ? ` - ${description}` : ''}`,
    )
    this.name = 'OAuthRequestError'
    this.statusCode = statusCode
    this.sentError = rawError !== undefined
    this.error = rfcErrorCode(rawError) ?? errorCodeFromMessage(description)
  }
}

/** RFC 6749 section 5.2 error codes, and the text the API's error wrapper puts in front of them. */
const RFC_ERROR_CODES = new Set([
  'invalid_request',
  'invalid_client',
  'invalid_grant',
  'unauthorized_client',
  'unsupported_grant_type',
  'invalid_scope',
  'server_error',
  'temporarily_unavailable',
])

/**
 * The shape of an RFC 6749 error code. Anything else from a server is free text.
 *
 * @internal
 */
export const OAUTH_ERROR_CODE = /^[a-z_]{1,64}$/

function rfcErrorCode(value: string | undefined): string | undefined {
  return value !== undefined && OAUTH_ERROR_CODE.test(value) ? value : undefined
}

/**
 * The API currently answers token endpoint failures in its generic error shape,
 * `{"statusCode": 400, "error": "Bad Request", "message": "Invalid grant: refresh token is invalid"}`,
 * where `error` is the HTTP reason phrase and the OAuth code survives only as the prefix of
 * `message`. Recover it from there, so a refused refresh token still reads as `invalid_grant`.
 * Remove once the endpoint sends the RFC 6749 body.
 */
function errorCodeFromMessage(message: string | undefined): string | undefined {
  const prefix = message?.split(':')[0]?.trim().toLowerCase().replace(/\s+/g, '_')
  return prefix && RFC_ERROR_CODES.has(prefix) ? prefix : undefined
}

/**
 * An OAuth request that did not answer in time. Transient, like a network error: it says nothing
 * about the session.
 *
 * @internal
 */
export class OAuthRequestTimeoutError extends Error {
  /** Lets the studio's request error handler treat it like any other network failure. */
  readonly isNetworkError = true

  constructor(url: string, timeoutMs: number, cause: unknown) {
    super(`OAuth request timed out after ${timeoutMs}ms: ${url}`, {cause})
    this.name = 'OAuthRequestTimeoutError'
  }
}

/**
 * Checks that a successful token endpoint body is a usable bearer token response. A 200 alone
 * does not guarantee it, and persisting a malformed body would store a credential that can never
 * authenticate.
 */
function toTokenResponse(body: unknown): OAuthTokenResponse {
  const response =
    typeof body === 'object' && body !== null ? (body as Record<string, unknown>) : {}
  const {access_token, token_type, expires_in, refresh_token} = response
  if (
    typeof access_token !== 'string' ||
    access_token.length === 0 ||
    typeof token_type !== 'string' ||
    token_type.toLowerCase() !== 'bearer' ||
    typeof expires_in !== 'number' ||
    !Number.isFinite(expires_in) ||
    expires_in <= 0 ||
    (refresh_token !== undefined && (typeof refresh_token !== 'string' || !refresh_token))
  ) {
    throw new Error('OAuth token endpoint returned a malformed token response')
  }
  const {refresh_token_timeout} = response
  return {
    access_token,
    token_type,
    expires_in,
    refresh_token,
    // Ignore a value that is not a positive number. The tokens are still good.
    ...(typeof refresh_token_timeout === 'number' &&
    Number.isFinite(refresh_token_timeout) &&
    refresh_token_timeout > 0
      ? {refresh_token_timeout}
      : {}),
  }
}

/** @internal */
export interface OAuthEndpoints {
  authorizeUrl: (params: {
    clientId: string
    redirectUri: string
    codeChallenge: string
    state: string
    /** `login` asks the authorization server for its login form, even with a session there. */
    prompt?: 'login'
  }) => string
  exchangeCode: (params: {
    clientId: string
    redirectUri: string
    code: string
    codeVerifier: string
  }) => Promise<OAuthTokenResponse>
  refresh: (params: {clientId: string; refreshToken: string}) => Promise<OAuthTokenResponse>
  revoke: (params: {clientId: string; token: string}) => Promise<void>
}

/**
 * How long an OAuth request may take. A refresh runs under a cross-tab lock that logout waits for,
 * so a request that never settles must not be able to hold it forever.
 */
const OAUTH_REQUEST_TIMEOUT_MS = 30_000

/** @internal */
export interface OAuthHosts {
  /** The authorization server's issuer identifier, the API origin, e.g. `https://api.sanity.io`. */
  issuer: string
  projectId: string
}

/**
 * The user authorizes on the issuer. The token and revocation requests, which the studio makes
 * with `fetch`, go to the project's API host instead: that host checks the origin against the
 * project's CORS settings, while the issuer's own host only allows a fixed list of origins
 * (localhost and sanity.studio), so a studio hosted anywhere else could not complete a sign-in.
 *
 * @param fetchImpl - `fetch`, injectable for tests
 * @param timeoutMs - Request timeout, injectable for tests
 * @internal
 */
export function createOAuthEndpoints(
  {issuer, projectId}: OAuthHosts,
  fetchImpl: typeof fetch = (...args) => fetch(...args),
  timeoutMs: number = OAUTH_REQUEST_TIMEOUT_MS,
): OAuthEndpoints {
  // The project host, the way the client derives it from `apiHost`.
  const [protocol, host] = issuer.split('://', 2)
  const projectHost = `${protocol}://${projectId}.${host}`
  const endpoint = (name: 'authorize' | 'token' | 'revoke') =>
    `${name === 'authorize' ? issuer : projectHost}/v1/auth/oauth/${name}`

  async function postForm<T>(url: string, fields: Record<string, string>): Promise<T> {
    const controller = new AbortController()
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs)
    try {
      return await request<T>(url, fields, controller.signal)
    } catch (err) {
      if (controller.signal.aborted) throw new OAuthRequestTimeoutError(url, timeoutMs, err)
      throw err
    } finally {
      clearTimeout(timeoutId)
    }
  }

  async function request<T>(
    url: string,
    fields: Record<string, string>,
    signal: AbortSignal,
  ): Promise<T> {
    const response = await fetchImpl(url, {
      signal,
      method: 'POST',
      headers: {
        'accept': 'application/json',
        'content-type': 'application/x-www-form-urlencoded',
      },
      body: new URLSearchParams(fields).toString(),
      // Never send the cookie of the session these endpoints manage.
      credentials: 'omit',
    })
    const text = await response.text()
    let body: unknown = text
    try {
      body = text ? JSON.parse(text) : undefined
    } catch {
      // Not JSON: keep the raw text for the error message.
    }
    if (!response.ok) throw new OAuthRequestError(response.status, body)
    return body as T
  }

  return {
    authorizeUrl: ({clientId, redirectUri, codeChallenge, state, prompt}) => {
      const url = new URL(endpoint('authorize'))
      const params = new URLSearchParams({
        response_type: 'code',
        client_id: clientId,
        redirect_uri: redirectUri,
        code_challenge: codeChallenge,
        code_challenge_method: 'S256',
        state,
        // RFC 8707: ask for a token limited to this project. Without it the server applies the
        // OAuth application's default resources, which may be another project. The server keeps
        // the resource with the grant and reuses it for the code exchange and every refresh, so
        // only this request names it.
        resource: `urn:io.sanity:project:${projectId}`,
      })
      // OpenID Connect `prompt=login`: show the login form instead of signing the user straight
      // in with an existing sanity.io session.
      if (prompt) params.set('prompt', prompt)
      url.search = params.toString()
      return url.toString()
    },

    exchangeCode: async ({clientId, redirectUri, code, codeVerifier}) =>
      toTokenResponse(
        await postForm(endpoint('token'), {
          grant_type: 'authorization_code',
          client_id: clientId,
          redirect_uri: redirectUri,
          code,
          code_verifier: codeVerifier,
        }),
      ),

    refresh: async ({clientId, refreshToken}) =>
      toTokenResponse(
        await postForm(endpoint('token'), {
          grant_type: 'refresh_token',
          client_id: clientId,
          refresh_token: refreshToken,
        }),
      ),

    // RFC 7009: the server answers 200 whether or not the token was valid.
    revoke: async ({clientId, token}) => {
      await postForm(endpoint('revoke'), {client_id: clientId, token})
    },
  }
}
