/* oxlint-disable i18next/no-literal-string */
import {Card, type CardTone, Inline} from '@sanity/ui'
import {Code, VStack} from 'ui5'

import {Tooltip} from '../../../../../../../../ui-components/tooltip/Tooltip'
import {type WeightedHit} from '../../../../../../../search/common/types'
import {debugScoreCard} from './DebugOverlay.css'

interface DebugScoreProps {
  data: WeightedHit
}

export function DebugOverlay({data}: DebugScoreProps) {
  const {score} = data

  let tone: CardTone = 'default'
  if (score <= 0.1) {
    tone = 'critical'
  } else if (score >= 0.5) {
    tone = 'primary'
  }

  const matchingStories = data.stories.filter((story) => story.score > 0)

  return (
    <>
      <Tooltip
        content={
          <VStack gap={2}>
            {matchingStories.length ? (
              <>
                {matchingStories.map((story) => (
                  <Inline key={story.path} gap={3}>
                    <Code
                      size={0}
                      style={{
                        fontWeight: 'var(--medium)',
                      }}
                      trim
                    >
                      {story.path}
                    </Code>
                    <Code size={0} trim>
                      {story.why}
                    </Code>
                  </Inline>
                ))}
              </>
            ) : (
              <Code size={0} trim>
                No matches
              </Code>
            )}
          </VStack>
        }
        placement="bottom-start"
        portal
      >
        <Card className={debugScoreCard} padding={1} shadow={1} tone={tone}>
          <Code size={0} trim>
            score: {score}
          </Code>
        </Card>
      </Tooltip>
    </>
  )
}
