import {isImageSource, isSanityImageUrl, parseImageAssetUrl} from '@sanity/asset-utils'
import {type SanityClient} from '@sanity/client'
import {DocumentIcon} from '@sanity/icons/Document'
import {WarningOutlineIcon} from '@sanity/icons/WarningOutline'
import {
  createImageUrlBuilder,
  type ImageUrlBuilder,
  type SanityImageSource,
} from '@sanity/image-url'
import {Card, Skeleton} from '@sanity/ui'
import {
  type ComponentType,
  type ElementType,
  isValidElement,
  memo,
  type ReactNode,
  useCallback,
  useMemo,
  useState,
} from 'react'
import {isValidElementType} from 'react-is'
import {Flex} from 'ui5'

import {
  isVideoAssetSource,
  type VideoAssetSource,
} from '../../../media-library/plugin/preview/isVideoAssetSource'
import {VideoThumbnail} from '../../../media-library/plugin/preview/VideoThumbnail'
import {renderPreviewNode, resolveBlockImageDimensions} from '../../components/previews/helpers'
import {
  type PreviewLayoutKey,
  type PreviewMediaDimensions,
  type PreviewProps,
} from '../../components/previews/types'
import {useAccessPolicy} from '../../form/inputs/files/ImageInput/useAccessPolicy'
import {useImageUrl} from '../../form/inputs/files/ImageInput/useImageUrl'
import {useClient} from '../../hooks/useClient'
import {DEFAULT_STUDIO_CLIENT_OPTIONS} from '../../studioClient'
import {isString} from '../../util/isString'
import {_previewComponents} from './_previewComponents'
import {PreviewTooltip, PreviewTooltipAnchor, type PreviewTooltipPlacement} from './PreviewTooltip'

function FallbackIcon() {
  return <DocumentIcon className="sanity-studio__preview-fallback-icon" />
}

// Stable per asset-ref media component. Preview prepare() recreates media objects on
// every title keystroke; a new function identity remounts VideoThumbnail and refetches.
type VideoMediaPreviewComponent = ComponentType<{
  dimensions: PreviewMediaDimensions
  layout: PreviewLayoutKey
}>
const videoMediaPreviewByAssetRef = new Map<string, VideoMediaPreviewComponent>()
const videoValueByAssetRef = new Map<string, VideoAssetSource>()

function getVideoMediaPreview(value: VideoAssetSource): VideoMediaPreviewComponent {
  const assetRef = value.asset._ref
  videoValueByAssetRef.set(assetRef, value)

  const existing = videoMediaPreviewByAssetRef.get(assetRef)
  if (existing) return existing

  function VideoMediaPreview({
    dimensions,
  }: {
    dimensions: PreviewMediaDimensions
    layout: PreviewLayoutKey
  }) {
    const current = videoValueByAssetRef.get(assetRef)
    return current ? <VideoThumbnail value={current} dimensions={dimensions} /> : null
  }

  videoMediaPreviewByAssetRef.set(assetRef, VideoMediaPreview)
  return VideoMediaPreview
}

/** @internal */
export interface SanityDefaultPreviewProps extends Omit<PreviewProps, 'renderDefault'> {
  error?: Error | null
  icon?: ElementType | false
  /** Opens on hover over the whole row, placed against the row's status */
  tooltip?: ReactNode
  tooltipPlacement?: PreviewTooltipPlacement
}

type SanityDefaultMediaProps = {
  client: SanityClient
  dimensions: PreviewMediaDimensions
  imageSource: SanityImageSource
  imageUrlBuilder: ImageUrlBuilder
  title: PreviewProps['title']
}

function SanityDefaultMedia({
  client,
  dimensions,
  imageSource,
  imageUrlBuilder,
  title,
}: SanityDefaultMediaProps) {
  const transform = (builder: ImageUrlBuilder, val: SanityImageSource) => {
    const width = dimensions.width ?? 100
    const height = dimensions.height ?? 100
    const fit = dimensions.fit
    const dpr = dimensions.dpr ?? 1

    return builder.image(val).withOptions({width, height, fit, dpr}).url() || ''
  }

  const accessPolicy = useAccessPolicy({client, source: imageSource})

  const {isLoading, url} = useImageUrl({
    accessPolicy,
    imageSource,
    imageUrlBuilder,
    transform,
  })

  const [hasImageError, setHasImageError] = useState(false)
  const handleError = () => setHasImageError(true)

  if (isLoading) {
    return <Skeleton animated style={{width: '100%', height: '100%'}} />
  }

  // Show a warning if we have a media library asset that we couldn't check
  // the access policy for (e.g., cookie auth) and the image failed to load
  const showAccessWarning = accessPolicy === 'unknown' && hasImageError

  if (showAccessWarning) {
    return (
      <Card tone="critical" style={{width: '100%', height: '100%'}}>
        <Flex justifyContent="center" alignItems="center" style={{width: '100%', height: '100%'}}>
          <WarningOutlineIcon />
        </Flex>
      </Card>
    )
  }

  return (
    <img
      alt={typeof title === 'string' ? title : undefined}
      onError={handleError}
      referrerPolicy="strict-origin-when-cross-origin"
      src={url}
    />
  )
}

/**
 * Used in cases where no custom preview component is provided
 * @internal
 * */
export const SanityDefaultPreview = memo(function SanityDefaultPreview(
  props: SanityDefaultPreviewProps,
): React.JSX.Element {
  const {
    icon: Icon,
    layout,
    media: mediaProp,
    imageUrl,
    status,
    title,
    tooltip,
    tooltipPlacement,
    ...restProps
  } = props
  const hasTooltip = Boolean(tooltip)

  const client = useClient(DEFAULT_STUDIO_CLIENT_OPTIONS)
  const imageBuilder = useMemo(() => createImageUrlBuilder(client), [client])

  // NOTE: This function exists because the previews provides options
  // for the rendering of the media (dimensions)
  const renderMedia = useCallback(
    (options: {dimensions: PreviewMediaDimensions}) => {
      let imageSource = mediaProp

      // If this is a string and a valid Sanity Image URL, parse it so that we can
      // pass it as a valid asset ID to the image builder
      if (isString(imageSource) && isSanityImageUrl(imageSource)) {
        const {assetId} = parseImageAssetUrl(imageSource)

        imageSource = assetId
      }

      return (
        <SanityDefaultMedia
          client={client}
          dimensions={options.dimensions}
          imageSource={imageSource as SanityImageSource}
          imageUrlBuilder={imageBuilder}
          title={title}
        />
      )
    },
    [client, imageBuilder, mediaProp, title],
  )

  const renderIcon = useCallback(() => {
    return Icon ? <Icon /> : <FallbackIcon />
  }, [Icon])

  const media = useMemo(() => {
    if (Icon === false) {
      // Explicitly disabled
      return false
    }

    // If this is a string and a valid Sanity Image URL, pass it to the renderMedia function early
    // If we don't do this check early, then isValidElementType will return true for strings and create an
    // exception when used inside the BlockImagePreview
    if (isString(mediaProp) && isSanityImageUrl(mediaProp)) {
      return renderMedia
    }

    if (isImageSource(mediaProp)) {
      return renderMedia
    }

    if (isVideoAssetSource(mediaProp)) {
      return getVideoMediaPreview(mediaProp)
    }

    if (isValidElementType(mediaProp)) {
      return mediaProp
    }

    if (isValidElement(mediaProp)) {
      return mediaProp
    }

    // Handle image urls
    if (isString(imageUrl)) {
      return (
        <img
          src={imageUrl}
          alt={isString(title) ? title : undefined}
          referrerPolicy="strict-origin-when-cross-origin"
        />
      )
    }

    // Render fallback icon
    return renderIcon
  }, [Icon, imageUrl, mediaProp, renderIcon, renderMedia, title])

  const resolvedMediaDimensions = useMemo<PreviewMediaDimensions | undefined>(() => {
    if (props.mediaDimensions) {
      return props.mediaDimensions
    }

    if (layout !== 'blockImage') {
      return undefined
    }

    if (!isImageSource(mediaProp)) {
      return undefined
    }

    return resolveBlockImageDimensions(mediaProp)
  }, [layout, mediaProp, props.mediaDimensions])

  const previewProps: Omit<PreviewProps, 'renderDefault'> = useMemo(
    () => ({
      ...restProps,
      media,
      mediaDimensions: resolvedMediaDimensions,
      status:
        hasTooltip && status ? (
          <PreviewTooltipAnchor>
            {renderPreviewNode(status, layout || 'default')}
          </PreviewTooltipAnchor>
        ) : (
          status
        ),
      title,
    }),
    [hasTooltip, layout, media, resolvedMediaDimensions, restProps, status, title],
  )

  const LayoutComponent = _previewComponents[layout || 'default'] as ComponentType<
    Omit<PreviewProps, 'renderDefault'>
  >

  const children = <LayoutComponent {...previewProps} />

  if (tooltip) {
    return (
      <PreviewTooltip content={tooltip} placement={tooltipPlacement}>
        {children}
      </PreviewTooltip>
    )
  }

  return children
})
