import {useTelemetry} from '@sanity/telemetry/react'
import {type ComponentType, type ReactNode, useContext, useEffect, useMemo, useState} from 'react'
import {useSyncObservable} from 'react-rx'
import {catchError, map, of} from 'rxjs'
import {RouterHistoryContext} from 'sanity/_singletons'

import {CapabilityGate} from '../components/CapabilityGate'
import {LoadingBlock} from '../components/loadingBlock/LoadingBlock'
import {isDashboardAuthStore} from '../store/auth/legacy/createLegacyAuthStore'
import {isOAuthAuthStore} from '../store/auth/oauth/createOAuthAuthStore'
import {type AuthStore} from '../store/auth/types'
import {useComlinkStore, useRenderingContextStore} from '../store/datastores'
import {ResourceCacheProvider} from '../store/ResourceCacheProvider'
import {
  AuthBoundaryResolved,
  OAuthCodeExchangeCompleted,
  OAuthOriginCheckFailed,
  OAuthRequestRetried,
  OAuthSessionEnded,
  OAuthSignInStarted,
  OAuthTokenRenewed,
  SessionTokenExchangeCompleted,
} from './__telemetry__/authBoundary.telemetry'
import {StudioAuthReadyMeasured} from './__telemetry__/bootstrap.telemetry'
import {useActiveWorkspace} from './activeWorkspaceMatcher/useActiveWorkspace'
import {AuthenticateScreen} from './screens/AuthenticateScreen'
import {NotAuthenticatedScreen} from './screens/NotAuthenticatedScreen'
import {RequestAccessScreen} from './screens/RequestAccessScreen'
import {getPageVisibilitySnapshot} from './telemetry/pageVisibility'

// Module-level one-shot guard. Survives StrictMode double-mount in dev so the
// event only fires once per page load (HMR resets this naturally).
let authReadyFired = false

interface AuthBoundaryProps {
  children: ReactNode
  AuthenticateComponent?: ComponentType
  LoadingComponent?: ComponentType
  NotAuthenticatedComponent?: ComponentType
}

type LoggedInState = 'logged-in' | 'logged-out' | 'loading' | 'unauthorized'

type AuthStatus = {
  loggedIn: LoggedInState
  loginProvider?: string
}

type AuthStatusResult = {type: 'value'; status: AuthStatus} | {type: 'error'; error: unknown}

const INITIAL_AUTH_STATUS: AuthStatus = {loggedIn: 'loading'}
const INITIAL_AUTH_RESULT: AuthStatusResult = {type: 'value', status: INITIAL_AUTH_STATUS}

export function AuthBoundary({
  children,
  AuthenticateComponent = AuthenticateScreen,
  LoadingComponent = LoadingBlock,
  NotAuthenticatedComponent = NotAuthenticatedScreen,
}: AuthBoundaryProps) {
  const [error, handleError] = useState<unknown>(null)
  if (error) throw error

  // The auth store whose callback flow (sid → credential exchange) has
  // settled. Until the ACTIVE workspace's store has, a logged-out state is
  // ambiguous — it may be the stale pre-exchange probe result — so the
  // render below holds the loading screen instead of flashing the login
  // screen. Store identity rather than a boolean, so a workspace switch
  // mid-exchange keeps the gate closed for the new workspace and a
  // superseded exchange settling late can't open it.
  const [callbackSettledFor, setCallbackSettledFor] = useState<AuthStore | undefined>(undefined)
  const {activeWorkspace} = useActiveWorkspace()
  const callbackSettled =
    !activeWorkspace.auth.handleCallbackUrl || callbackSettledFor === activeWorkspace.auth
  const telemetry = useTelemetry()
  const [mountTime] = useState(() => performance.now())
  // Read without the throwing hook: an AuthBoundary rendered outside the Studio's router has no
  // history to keep in sync.
  const routerHistory = useContext(RouterHistoryContext)

  const authStatus$ = useMemo(
    () =>
      activeWorkspace.auth.state.pipe(
        map(({authenticated, currentUser}): AuthStatusResult => {
          /**
           * If a user has never had any roles on for the given workspace project
           * e.g. because they've only ever been an organization member thereby
           * giving them implicit access to the studio then they will have no roles
           * array on their user so to account for this case or the case that they have
           * had roles removed then we need to set the logged in state to unauthorized.
           */
          if (
            authenticated &&
            (!Array.isArray(currentUser?.roles) || currentUser.roles.length === 0)
          ) {
            return {
              type: 'value',
              status: {
                loggedIn: 'unauthorized',
                loginProvider: currentUser?.provider,
              },
            }
          }

          return {
            type: 'value',
            status: {loggedIn: authenticated ? 'logged-in' : 'logged-out'},
          }
        }),
        catchError((err: unknown) => of({type: 'error' as const, error: err})),
      ),
    [activeWorkspace],
  )

  // Kept synchronous: this gates authenticated children and is compared with
  // the live `callbackSettled` state — a deferred snapshot could keep children
  // mounted after logout or pair stale `loggedIn` with fresh settlement state.
  const authResult = useSyncObservable(authStatus$, INITIAL_AUTH_RESULT)
  if (authResult.type === 'error') throw authResult.error

  const {loggedIn, loginProvider} = authResult.status

  // AuthBoundaryResolved: mount-baseline — measures time from this component
  // mounting to auth state resolving. Fires every transition out of 'loading'.
  useEffect(() => {
    if (loggedIn !== 'loading') {
      telemetry.log(AuthBoundaryResolved, {
        durationMs: Math.round(performance.now() - mountTime),
        result: loggedIn,
      })
    }
  }, [loggedIn, telemetry, mountTime])

  // StudioAuthReadyMeasured: navigation-start baseline — measures time from
  // performance.timeOrigin (pairs with web-vitals metrics like LCP/FCP).
  // One-shot via module-level guard.
  useEffect(() => {
    if (authReadyFired) return
    if (loggedIn === 'loading') return
    authReadyFired = true
    const durationMs = performance.now()
    telemetry.log(StudioAuthReadyMeasured, {
      durationMs,
      authState: loggedIn,
      ...getPageVisibilitySnapshot(durationMs),
    })
  }, [loggedIn, telemetry])

  useEffect(() => {
    const auth = activeWorkspace.auth
    // A superseded run (workspace switched away, or StrictMode's first
    // invocation) must not write: a stale store settling late would
    // overwrite the ACTIVE store's settled marker and re-close the gate,
    // stranding a logged-out user on the loading screen.
    let superseded = false
    // Only a history that mirrors the address bar can be brought up to date from it. A custom
    // `unstable_history` (a hash history, an embedding app's router) maps URLs its own way.
    const urlBefore = readLocation(window.location)
    const mirrorsAddressBar =
      routerHistory !== null && isSameLocation(readLocation(routerHistory.location), urlBefore)
    // A store rewrites the URL with the native History API while it handles the callback (it
    // removes the response parameters and returns to the page the user signed in from). The
    // router's history cached the URL before that and never sees the change, so bring it up to
    // date from the address bar.
    const syncRouterWithAddressBar = () => {
      if (!mirrorsAddressBar || !routerHistory) return
      const urlNow = readLocation(window.location)
      if (!isSameLocation(urlNow, readLocation(routerHistory.location))) {
        routerHistory.replace(urlNow)
      }
    }

    const callbackHandled = auth.handleCallbackUrl?.()
    // The response parameters leave the URL before `handleCallbackUrl` returns, and the router
    // must not hand them to a redirect or a link while the code exchange is out.
    syncRouterWithAddressBar()
    callbackHandled
      ?.then((result) => {
        if (result.loginMethod === 'oauth') {
          // Only the event's own fields: a field added to the result later is not sent with it.
          const {
            flow,
            success,
            durationMs,
            exchangeDurationMs,
            failureReason,
            stateSettleDurationMs,
            stateSettleTimedOut,
          } = result
          telemetry.log(OAuthCodeExchangeCompleted, {
            flow,
            success,
            durationMs,
            exchangeDurationMs,
            failureReason,
            stateSettleDurationMs,
            stateSettleTimedOut,
          })
        } else {
          telemetry.log(SessionTokenExchangeCompleted, result)
        }
      })
      .catch(handleError)
      .finally(() => {
        if (superseded) return
        // The store may return to the page the user signed in from once the exchange is done.
        syncRouterWithAddressBar()
        setCallbackSettledFor(auth)
      })
    return () => {
      superseded = true
    }
  }, [activeWorkspace.auth, routerHistory, telemetry])

  // The OAuth store reports its renewals and session ends as events already reduced to what is
  // safe to send (see `store/auth/oauth/telemetry.ts`); log them as they come.
  useEffect(() => {
    const auth = activeWorkspace.auth
    if (!isOAuthAuthStore(auth)) return undefined
    const subscription = auth.telemetryEvents.subscribe((event) => {
      switch (event.type) {
        case 'token-renewed': {
          const {type: _type, ...data} = event
          telemetry.log(OAuthTokenRenewed, data)
          break
        }
        case 'session-ended': {
          const {type: _type, ...data} = event
          telemetry.log(OAuthSessionEnded, data)
          break
        }
        case 'sign-in-started':
          telemetry.log(OAuthSignInStarted, {})
          break
        case 'request-retried': {
          const {type: _type, ...data} = event
          telemetry.log(OAuthRequestRetried, data)
          break
        }
        case 'origin-check-failed': {
          const {type: _type, ...data} = event
          telemetry.log(OAuthOriginCheckFailed, data)
          break
        }
      }
    })
    return () => subscription.unsubscribe()
  }, [activeWorkspace.auth, telemetry])

  if (loggedIn === 'loading') return <LoadingComponent />

  if (loggedIn === 'unauthorized') {
    // If using unverified `sanity` login provider, send them
    // to basic NotAuthorized component.
    if (!loginProvider || loginProvider === 'sanity') return <NotAuthenticatedComponent />
    return (
      <>
        <ResourceCacheProvider>
          <CapabilityGate capability="dashboard" condition="available">
            <HostAccessRequest projectId={activeWorkspace.projectId} />
          </CapabilityGate>
        </ResourceCacheProvider>
        <RequestAccessScreen />
      </>
    )
  }

  // While the callback exchange is unsettled, logged-out may be the stale
  // pre-exchange state — rendering the login screen on it is the flash this
  // gate prevents. handleCallbackUrl resolves only after the state reflects
  // the exchange, so once the gate opens, `loggedIn` can be trusted.
  if (loggedIn === 'logged-out' && !callbackSettled) return <LoadingComponent />

  // A message bus host owns sign-in and hands Studio a new token once the user signs in again.
  if (loggedIn === 'logged-out' && isDashboardAuthStore(activeWorkspace.auth)) {
    return <LoadingComponent />
  }

  if (loggedIn === 'logged-out') return <AuthenticateComponent />

  return <>{children}</>
}

function HostAccessRequest({projectId}: {projectId: string}): null {
  const messageBusConnection = useRenderingContextStore().getMessageBusConnection()
  const {node} = useComlinkStore()

  useEffect(() => {
    const request = {resourceType: 'project', resourceId: projectId} as const

    if (messageBusConnection) {
      messageBusConnection.emit('access.request', request).then(
        (reply) => {
          if (!reply.ok) console.warn('The dashboard declined the access request', reply)
        },
        (error: unknown) => console.warn('Requesting access from the dashboard failed', error),
      )

      return undefined
    }

    // Comlink would deliver a request queued before the handshake even after Studio has moved on.
    return node?.onStatus((status) => {
      if (status !== 'connected') return
      void node.fetch('dashboard/v1/auth/access/request', request).then(undefined, () => {})
    })
  }, [messageBusConnection, node, projectId])

  return null
}

interface UrlLocation {
  pathname: string
  search: string
  hash: string
}

function readLocation({pathname, search, hash}: UrlLocation): UrlLocation {
  return {pathname, search, hash}
}

function isSameLocation(a: UrlLocation, b: UrlLocation): boolean {
  return a.pathname === b.pathname && a.search === b.search && a.hash === b.hash
}
